def is_balanced(s):
    """True if every bracket in s is properly nested."""
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)              # push opener
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False              # mismatched or empty stack
            stack.pop()                   # consume the matching opener
    return not stack                      # all openers consumed?

print(is_balanced("([{}])"))   # True
print(is_balanced("([)]"))     # False - ] arrives but ( is on top

